/* ---------- claim ledger ---------- */
.claims{border:1px solid var(--rule);background:#fff;margin-block-start:30px}
.band--tone .claims{background:var(--paper)}
.claims__head{
  display:grid;grid-template-columns:1.15fr 120px 1.5fr;gap:20px;padding:13px 22px;
  border-block-end:1px solid var(--rule);background:var(--tone);
