/* ---------- do / do not ---------- */
.stance{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--rule);border:1px solid var(--rule);margin-block-start:30px}
.stance__col{background:#fff;padding:26px 26px 30px}
.band--tone .stance__col{background:var(--paper)}
.stance__h{display:flex;align-items:center;gap:12px;margin-block-end:18px;padding-block-end:14px;border-block-end:1px solid var(--rule)}
.stance__ic{position:relative;flex:0 0 34px;width:34px;height:34px;border-radius:3px;display:grid;place-items:center;overflow:hidden}
.stance__ic::before{content:"";position:absolute;inset:0;background:var(--sc);opacity:.12}
.stance__ic svg{position:relative;width:18px;height:18px;stroke:var(--sc);fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
