.claim__v--y{color:#2F6E52;background:rgba(47,110,82,.11)}
.claim__q{font-style:normal;font-family:var(--display);font-size:18px;color:var(--ink);line-height:1.3}
.claim__q::before,.claim__q::after{content:none}
/* ---------- primary navigation ---------- */
.top{position:sticky;top:0;z-index:60;background:var(--paper);border-block-end:1px solid var(--rule)}
.top__in{display:flex;align-items:center;gap:28px;padding-block:15px}
.mark{font-family:var(--display);font-size:22px;letter-spacing:.02em;text-decoration:none;color:var(--ink);white-space:nowrap}
.mark span{color:var(--seal);padding-inline:2px}
.nav{display:flex;align-items:center;gap:2px;margin-inline-start:auto}
.nav__item{position:relative}
.nav__top{
  display:flex;align-items:center;gap:6px;padding:9px 13px;font-size:15.5px;color:var(--ink);
  text-decoration:none;border-radius:3px;background:none;border:0;font-family:inherit;cursor:pointer;
  transition:background .2s ease,color .2s ease;
}
.nav__top:hover,.nav__item:focus-within .nav__top{background:var(--tone);color:var(--seal)}
.nav__top svg{width:11px;height:11px;stroke:currentColor;fill:none;stroke-width:2;transition:transform .25s ease}
.nav__item:hover .nav__top svg,.nav__item:focus-within .nav__top svg{transform:rotate(180deg)}

/* the panel */
.mega{
  position:absolute;inset-block-start:calc(100% + 8px);inset-inline-start:50%;transform:translateX(-50%) translateY(-6px);
  background:#fff;border:1px solid var(--rule);box-shadow:0 26px 60px -34px rgba(18,51,44,.5);
  opacity:0;visibility:hidden;transition:opacity .2s ease,transform .24s ease,visibility .2s;
  padding:26px;z-index:70;
}
.nav__item:hover .mega,.nav__item:focus-within .mega{opacity:1;visibility:visible;transform:translateX(-50%) translateY(0)}
.mega::before{content:"";position:absolute;inset-block-end:100%;inset-inline:0;height:12px}
.mega__grid{display:grid;gap:26px}
.mega--wide .mega__grid{grid-template-columns:repeat(3,minmax(210px,1fr));width:min(88vw,760px)}
.mega--mid .mega__grid{grid-template-columns:repeat(2,minmax(210px,1fr));width:min(80vw,520px)}
