.mega__k{
  font-family:var(--data);font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);
  display:block;margin-block-end:11px;padding-block-end:8px;border-block-end:1px solid var(--rule);
}
.mega a{
  position:relative;display:flex;align-items:flex-start;gap:11px;padding:8px 9px;margin-inline:-9px;
  text-decoration:none;border-radius:3px;transition:background .18s ease;
}
.mega a:hover{background:color-mix(in srgb,var(--c,var(--seal)) 8%,transparent)}
.mega__ic{position:relative;flex:0 0 28px;width:28px;height:28px;border-radius:3px;display:grid;place-items:center;overflow:hidden;margin-block-start:1px}
.mega__ic::before{content:"";position:absolute;inset:0;background:var(--c,var(--seal));opacity:.12;transition:opacity .2s ease}
.mega__ic svg{position:relative;width:15px;height:15px;stroke:var(--c,var(--seal));fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;transition:stroke .2s ease}
.mega a:hover .mega__ic::before{opacity:1}
.mega a:hover .mega__ic svg{stroke:#fff}
.mega__t{display:block;font-size:15px;line-height:1.3;color:var(--ink)}
.mega a:hover .mega__t{color:var(--c,var(--seal))}
.mega__d{display:block;font-size:12.5px;line-height:1.4;color:var(--muted);margin-block-start:2px}
.mega__foot{
  grid-column:1/-1;margin-block-start:6px;padding-block-start:16px;border-block-start:1px solid var(--rule);
  display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;
}
.mega__note{font-size:13px;color:var(--muted);margin:0;max-width:46ch}
.mega__all{font-family:var(--data);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--seal);text-decoration:none;white-space:nowrap;padding:0!important;margin:0!important}
