/* ---------- commitments / limits ---------- */
.pledge{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-block-start:30px}
.pcol{border:1px solid var(--rule);background:#fff;overflow:hidden;animation:tibRise .6s ease var(--d,0ms) both}
.band--tone .pcol{background:var(--paper)}
.pcol__h{display:flex;align-items:center;gap:13px;padding:20px 24px;border-block-end:1px solid var(--rule);background:var(--tone)}
.band--tone .pcol__h{background:#fff}
.pcol__ic{position:relative;flex:0 0 36px;width:36px;height:36px;border-radius:3px;display:grid;place-items:center;overflow:hidden}
.pcol__ic::before{content:"";position:absolute;inset:0;background:var(--pc);opacity:.13}
.pcol__ic svg{position:relative;width:19px;height:19px;stroke:var(--pc);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.pcol__t{flex:1;min-width:0}
