/* ---------- why India ---------- */
.why{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px;margin-block-start:32px}
.wcard{
  position:relative;border:1px solid var(--rule);background:#fff;overflow:hidden;
  padding:26px 26px 28px;animation:tibRise .6s ease var(--d,0ms) both;
  transition:border-color .3s ease,box-shadow .3s ease,transform .3s ease;
}
.band--tone .wcard{background:var(--paper)}
.wcard::before{
  content:"";position:absolute;inset-block-start:0;inset-inline:0;height:2px;background:var(--c);
  transform:scaleX(0);transform-origin:left;transition:transform .5s cubic-bezier(.4,0,.2,1);
}
.wcard:hover::before{transform:scaleX(1)}
.wcard:hover{border-color:var(--c);box-shadow:0 20px 44px -34px rgba(18,51,44,.5);transform:translateY(-2px)}
.wcard__n{
  position:absolute;inset-block-start:20px;inset-inline-end:22px;
  font-family:var(--display);font-size:44px;line-height:1;color:var(--c);opacity:.13;
  transition:opacity .3s ease;
}
.wcard:hover .wcard__n{opacity:.24}
.wcard__ic{
  position:relative;width:48px;height:48px;border-radius:3px;display:grid;place-items:center;
  overflow:hidden;margin-block-end:18px;
}
.wcard__ic::before{content:"";position:absolute;inset:0;background:var(--c);opacity:.12;transition:opacity .3s ease}
.wcard__ic svg{position:relative;width:25px;height:25px;stroke:var(--c);fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;transition:stroke .3s ease}
.wcard:hover .wcard__ic::before{opacity:1}
.wcard:hover .wcard__ic svg{stroke:#fff}
.wcard h3{font-size:20px;line-height:1.25;margin:0 0 4px}
