}
.js-motion .wcard:not(.seen) .wmeter__b{transform:scaleX(0)}
.wmeter__b{transform:none}
.wmeter__b.on{background:var(--c)}
.wmeter__l{
  font-family:var(--data);font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--c);
}
.wcard p{font-size:14.5px;line-height:1.62;color:var(--ink-soft);margin:0}
.wcard p b{color:var(--ink);font-weight:600}
@media(max-width:560px){.wcard{padding:22px 20px 24px}.wcard__n{font-size:36px}}
/* ---------- scroll motion (progressive enhancement) ----------
   Every hiding rule below is scoped to .js-motion, which only exists
   once JavaScript has actually run. No JS = nothing hidden, ever. */
.js-motion .rise:not(.seen),
.js-motion .wcard:not(.seen),
.js-motion .pcol:not(.seen),
