.js-motion .rise{transform:translateY(26px);transition:opacity .7s cubic-bezier(.16,1,.3,1),transform .7s cubic-bezier(.16,1,.3,1)}
.js-motion .spec,.js-motion .proc,.js-motion .opt,.js-motion .warn{
  transform:translateY(30px) scale(.985);
  transition:opacity .6s cubic-bezier(.16,1,.3,1) var(--sd,0ms),transform .6s cubic-bezier(.16,1,.3,1) var(--sd,0ms),border-color .25s ease,box-shadow .25s ease;
